200	    function addPhotoToAlbum(albumId, photoUrl) {
201	        const photosContainer = document.getElementById(`album-${albumId}-photos`);
202	        const photoDiv = document.createElement('div');
203	        photoDiv.className = 'photo-item';
204	        photoDiv.innerHTML = `
205	            <img src="${photoUrl}" class="photo-preview" alt="Foto do álbum" />
206	            <div class="photo-info">
207	                <div class="photo-url-display">${photoUrl}</div>
208	                <input type="hidden" class="photo-url" value="${photoUrl}" />
209	            </div>
210	            <button type="button" class="btn-remove" data-action="remove-photo">Remover</button>
211	        `;
212	        photosContainer.appendChild(photoDiv);
213	    }
