216	    async function uploadFile(file) {
217	        const formData = new FormData();
218	        formData.append('image', file);
219	        try {
220	            const res = await fetch('/api/upload', { method: 'POST', body: formData });
221	            if (!res.ok) {
222	                const errorData = await res.json().catch(() => ({ error: 'Falha no upload' }));
223	                throw new Error(errorData.error);
224	            }
225	            const result = await res.json();
226	            return result.url;
227	        } catch (err) {
228	            throw new Error(`Erro no upload: ${err.message}`);
229	        }
